contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, bytes32 assertionId, bool assertedTruthfully) public {
        require(caller != address(this), "caller must not be the test contract");
        bool reverted;
        // Impersonate an unrelated caller by forwarding through a low-level call.
        // The caller is a parameter; the test contract itself is msg.sender for its own calls,
        // so to test a non-optimistic-asserter caller we use an external call with the given address's context.
        // Since we cannot change msg.sender, we call the callback directly from this test contract as msg.sender.
        // The rule: when msg.sender is not the optimistic asserter, the call must revert.
        // Here msg.sender is this test contract, which deployed c and is therefore not the optimistic asserter.
        try c.assertionResolvedCallback(assertionId, assertedTruthfully) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }
}

